    if len(text) == 0:
        return ''
    text = text.lower()
    return text[0].upper() + text[1:]

def f(text, suffix):
    if suffix.startswith("/"):
        return text + suffix[1:]
    return text

def f(text, n):
    if n < 0 or len(text) <= n:
        return text
    result = text[0 : n]
    i = len(result) - 1
    while i >= 0:
        if result[i] != text[i]:
            break
        i -= 1
    return text[0 : i + 1]

def f(integer, n):
    i = 1
    text = str(integer)
    while (i+len(text) < n):
        i += len(text)
    return text.zfill(i+len(text))

def f(l1, l2):
    if len(l1) != len(l2):
        return {}
    return dict.fromkeys(l1, l2)

def f(list, start, end):
    count = 0
    for i in range(start, end):
        for j in range(i, end):
            if list[i] != list[j]:
                count += 1
    return count

def f(line):
    a = []
    for c in line:
        if c.isalnum():
            a.append(c)
    return ''.join(a)

def f(text, pre):
    if not text.startswith(pre):
        return text
    return text.removeprefix(pre)
